I was able to create a conversation flow with my requirements + add agents for general questions and code execution. I'm sharing my current implementation with the hope it might be useful to others.

### Code: 

```py
from autogen.agentchat.groupchat import GroupChat
from autogen.agentchat.agent import Agent
from autogen.agentchat.assistant_agent import AssistantAgent

class CustomGroupChat(GroupChat):
    def __init__(self, agents, messages, max_round=10):
        super().__init__(agents, messages, max_round)
        self.previous_speaker = None  # Keep track of the previous speaker
    
    def select_speaker(self, last_speaker: Agent, selector: AssistantAgent):
        # Check if last message suggests a next speaker or termination
        last_message = self.messages[-1] if self.messages else None
        if last_message:
            if 'NEXT:' in last_message['content']:
                # if there is a suggested agent to speak next, pick them
                suggested_next = last_message['content'].split('NEXT: ')[-1].strip()
                print(f'Extracted suggested_next = {suggested_next}')
                try:
                    return self.agent_by_name(suggested_next)
                except ValueError:
                    return None  # If agent name is not valid, something went wrong
            
            elif 'TERMINATE' in last_message['content']:
                # termination gives back control to user
                return self.agent_by_name('User')
                    
            elif 'execution failed' in last_message['content']:
                # that means the executor spoke and there was an error
                # return control back to coder
                return self.agent_by_name('Coder')
        
        if last_speaker.name == "User":
            # the user should always prompt the commander
            return self.agent_by_name('Commander')

        elif last_speaker.name == "Data_Parser":
            # data parser gives control to coder
            return self.agent_by_name('Coder')

        elif last_speaker.name == "Coder":
            # coder gives control to executor
            return self.agent_by_name('Executor')
            
        elif last_speaker.name in ["General_Assistant", "Executor"]:
            # the leaf workers have spoken now
            # return control to the user
            return self.agent_by_name('User')

        else:
            # this would be an invalid state
            return None
        
        self.previous_speaker = last_speaker

```

