using AutoGen.Core;
using AutoGen.OpenAI;
using Azure.AI.OpenAI;

namespace AutoGen.BasicSample;

/// <summary>
/// This example shows usage of ImageMessage. The image is loaded as BinaryData and sent to GPT-4V 
/// <br>
