            Console.WriteLine("Streaming chat where the client constructs the final message from the streamed content");
            var userTextMessage = new TextMessage(Role.User, "Hello AI!");
            var reply = ollamaAgent.GenerateStreamingReplyAsync([userTextMessage]);
            var finalTextMessage = new TextMessage(Role.Assistant, string.Empty, from: ollamaAgent.Name); // updating this message based off the reply stream
            await foreach (var message in reply)
            {
                if (message is TextMessageUpdate textMessage)
                {
                    finalTextMessage.Update(textMessage); // add the streamed content to the final message
                }
                else if (message is TextMessage txtMessage) // the final message from the stream
                {
                    // discard the stream's generated final message
                }
            }

            // finalTextMessage will contain the final message with all the streamed content
            if (finalTextMessage == null)
            {
                throw new Exception("finalTextMessage is null");
            }
