async def assistant_run(self, question) -> Tuple[str, int]:
        with LLMObs.workflow(name=self.agent_version, session_id=self.conversation_id):
            if self.workflow_config:
                result = self.workflow_executor.execute(self.workflow_config)
                if result:
                    question += " " + result

            termination = MaxMessageTermination(
                max_messages=self.max_consecutive_auto_reply
            ) | TextMentionTermination("TERMINATE")

            if self.team_config["type"] == "swarm":
                self.agents.sort(
                    key=lambda agent: (
                        0 if "planner" in agent.name.lower() else 1,
                        agent.name,
                    )
                )
                agent_team = Swarm(self.agents, termination_condition=termination)
            elif self.team_config["type"] == "graph":
                # Create a directed graph using DiGraphBuilder
                builder = DiGraphBuilder()

                for agent in self.agents:
                    builder.add_node(agent)

                graph_config = self.team_config.get("graph_config", {})
                edges = graph_config.get("edges", [])

                for edge in edges:
                    source = edge.get("source")
                    target = edge.get("target")
                    condition = edge.get("condition")

                    source_agent = next(
                        (a for a in self.agents if a.name == source), None
                    )
                    target_agent = next(
                        (a for a in self.agents if a.name == target), None
                    )

                    if source_agent and target_agent:
                        if condition:
                            builder.add_edge(
                                source_agent, target_agent, condition=condition
                            )
                        else:
                            builder.add_edge(source_agent, target_agent)
                            self.logger.info(f"Added edge: {source} -> {target}")
                    else:
                        self.logger.error(
                            f"Failed to add edge - source or target agent not found: {source} -> {target}"
                        )

                # Build and validate the graph
                graph = builder.build()

                self.logger.info("Graph structure:")
                self.logger.info(f"Nodes: {list(graph.nodes.keys())}")
                for node_name, node in graph.nodes.items():
                    self.logger.info(
                        f"Node '{node_name}' edges: {[e.target + (f' [condition: {e.condition}]' if e.condition else '') for e in node.edges]}"
                    )
                self.logger.info(f"Start nodes: {graph.get_start_nodes()}")
                self.logger.info(f"Leaf nodes: {graph.get_leaf_nodes()}")
                self.logger.info(f"Has cycles: {graph.get_has_cycles()}")

                # Create the GraphFlow team
                agent_team = GraphFlow(
                    self.agents, graph=graph, termination_condition=termination
                )

                self.logger.info("GraphFlow team created - beginning execution")
                self.logger.info(
                    f"Agent names: {[agent.name for agent in self.agents]}"
                )
